<?php
require_once __DIR__.'/../config.php'; require_login();
$tab=$_GET['tab']??'services';
$canManageOperationalData=in_array(role(),['data_entry','super_admin'],true);
$canManageDocuments=in_array(role(),['admin','data_entry','super_admin'],true);
if(!$canManageOperationalData && !($canManageDocuments && $tab==='documents')) redirect('dashboard.php');
$msg='';$err='';
function go_tab($t){header('Location: data_entry.php?tab='.urlencode($t));exit;}
if($_SERVER['REQUEST_METHOD']==='POST'){
 $entity=$_POST['entity']??'';$op=$_POST['op']??'save';$id=(int)($_POST['id']??0);
 try{
  if($entity==='documents'){
    if(!$canManageDocuments || $tab!=='documents') throw new RuntimeException('document access');
    $titleEn=trim($_POST['title_en']??'');$titleSi=trim($_POST['title_si']??'');$active=isset($_POST['active'])?1:0;
    if($titleEn==='' || $titleSi==='') throw new RuntimeException('document title');
    $upload=$_FILES['document_file']??null;$newFileName=null;$newFilePath=null;
    if($upload && $upload['error']!==UPLOAD_ERR_NO_FILE){
      if($upload['error']!==UPLOAD_ERR_OK || $upload['size']>10485760 || strtolower(pathinfo($upload['name'],PATHINFO_EXTENSION))!=='pdf') throw new RuntimeException('document upload');
      $fileInfo=new finfo(FILEINFO_MIME_TYPE);
      if($fileInfo->file($upload['tmp_name'])!=='application/pdf') throw new RuntimeException('document type');
      $directory=realpath(__DIR__.'/../documents');
      if($directory===false) throw new RuntimeException('document directory');
      $newFileName='document_'.bin2hex(random_bytes(8)).'.pdf';
      if(!move_uploaded_file($upload['tmp_name'],$directory.DIRECTORY_SEPARATOR.$newFileName)) throw new RuntimeException('document move');
      $newFilePath='documents/'.$newFileName;
    }
    if($id){
      if($newFileName!==null){$s=$conn->prepare('UPDATE documents SET title_en=?,title_si=?,file_name=?,file_path=?,active=? WHERE id=?');$s->bind_param('ssssii',$titleEn,$titleSi,$newFileName,$newFilePath,$active,$id);}
      else{$s=$conn->prepare('UPDATE documents SET title_en=?,title_si=?,active=? WHERE id=?');$s->bind_param('ssii',$titleEn,$titleSi,$active,$id);}
    }else{
      if($newFileName===null) throw new RuntimeException('document file required');
      $s=$conn->prepare('INSERT INTO documents(title_en,title_si,file_name,file_path,active) VALUES(?,?,?,?,?)');
      $s->bind_param('ssssi',$titleEn,$titleSi,$newFileName,$newFilePath,$active);
    }
    if(!$s || !$s->execute()) throw new RuntimeException('document save');$msg='Document saved.';$tab='documents';
  }
  elseif($entity==='services'){ $en=trim($_POST['name_en']??'');$si=trim($_POST['name_si']??'');$cat=trim($_POST['category']??'');if($id){$s=$conn->prepare('UPDATE services SET name_en=?,name_si=?,category=? WHERE id=?');$s->bind_param('sssi',$en,$si,$cat,$id);}else{$s=$conn->prepare('INSERT INTO services(name_en,name_si,category) VALUES(?,?,?)');$s->bind_param('sss',$en,$si,$cat);}if(!$s || !$s->execute()) throw new RuntimeException('service');$msg='Service saved.';$tab='services';}
  elseif($entity==='vehicles'){ $type=trim($_POST['vehicle_type']??'');$reg=trim($_POST['registration_no']??'');$opn=trim($_POST['operator_name']??'');$route=trim($_POST['route']??'');if($id){$s=$conn->prepare('UPDATE vehicles SET vehicle_type=?,registration_no=?,operator_name=?,route=? WHERE id=?');$s->bind_param('ssssi',$type,$reg,$opn,$route,$id);}else{$s=$conn->prepare('INSERT INTO vehicles(vehicle_type,registration_no,operator_name,route) VALUES(?,?,?,?)');$s->bind_param('ssss',$type,$reg,$opn,$route);}if(!$s || !$s->execute()) throw new RuntimeException('vehicle');$msg='Vehicle saved.';$tab='vehicles';}
  elseif($entity==='stands'){ $name=trim($_POST['name']??'');$district=trim($_POST['district']??'');$address=trim($_POST['address']??'');if($id){$s=$conn->prepare('UPDATE bus_stands SET name=?,district=?,address=? WHERE id=?');$s->bind_param('sssi',$name,$district,$address,$id);}else{$s=$conn->prepare('INSERT INTO bus_stands(name,district,address) VALUES(?,?,?)');$s->bind_param('sss',$name,$district,$address);}if(!$s || !$s->execute()) throw new RuntimeException('stand');$msg='Bus stand saved.';$tab='stands';}
  elseif($entity==='faqs'){ $intent=trim($_POST['intent']??'');$q=trim($_POST['question']??'');$a=trim($_POST['answer']??'');$language=$_POST['language']??'en';if($id){$s=$conn->prepare('UPDATE faqs SET intent=?,question=?,answer=?,language=? WHERE id=?');$s->bind_param('ssssi',$intent,$q,$a,$language,$id);}else{$s=$conn->prepare('INSERT INTO faqs(intent,question,answer,language) VALUES(?,?,?,?)');$s->bind_param('ssss',$intent,$q,$a,$language);}if(!$s || !$s->execute()) throw new RuntimeException('faq');$msg='FAQ saved.';$tab='faqs';}
  elseif($entity==='delete'){
    $type=$_POST['type']??'';
    if($type==='documents' && $canManageDocuments && $tab==='documents'){$s=$conn->prepare('UPDATE documents SET active=0 WHERE id=?');$s->bind_param('i',$id);if(!$s || !$s->execute()) throw new RuntimeException('document disable');$msg='Document removed from the client list.';$tab='documents';}
    else{$map=['services'=>'services','vehicles'=>'vehicles','stands'=>'bus_stands','faqs'=>'faqs'];if(isset($map[$type])){$s=$conn->prepare('DELETE FROM '.$map[$type].' WHERE id=?');$s->bind_param('i',$id);if(!$s || !$s->execute()) throw new RuntimeException('delete');$msg='Record deleted.';$tab=$type;}}
  }
 }catch(Throwable $e){$err='Could not save this record. Please check the fields and try again.';}
}
$editId=(int)($_GET['edit']??0);$editRow=null;if($editId){$table=$tab==='services'?'services':($tab==='vehicles'?'vehicles':($tab==='stands'?'bus_stands':($tab==='documents'?'documents':'faqs')));$q=$conn->prepare('SELECT * FROM '.$table.' WHERE id=?'); if($q){$q->bind_param('i',$editId);$q->execute();$editRow=$q->get_result()->fetch_assoc();}}
$title='Data Entry Management';include '../includes/header.php';
?>
