<?php if($msg):?><div class="notice success"><?=h($msg)?></div><?php endif;?><?php if($err):?><div class="notice danger"><?=h($err)?></div><?php endif;?>
<div class="tabs"><?php if($canManageOperationalData):?><a class="<?= $tab==='services'?'active':''?>" href="?tab=services">Services</a><a class="<?= $tab==='vehicles'?'active':''?>" href="?tab=vehicles">Vehicles</a><a class="<?= $tab==='stands'?'active':''?>" href="?tab=stands">Bus Stands</a><a class="<?= $tab==='faqs'?'active':''?>" href="?tab=faqs">FAQ / AI</a><?php endif;?><a class="<?= $tab==='documents'?'active':''?>" href="?tab=documents">Documents</a></div>
<?php if($tab==='services'):?><div class="crud-grid"><div class="form-card"><h3><?= $editRow?"Edit Service":"Add Service" ?></h3><form method="post"><input type="hidden" name="entity" value="services"><input type="hidden" name="id" value="<?= (int)($editRow["id"]??0) ?>"><label>English name</label><input name="name_en" value="<?=h($editRow["name_en"]??"")?>" required><label>Sinhala name</label><input name="name_si" value="<?=h($editRow["name_si"]??"")?>" required><label>Category</label><input name="category" value="<?=h($editRow["category"]??"")?>" required><button class="primary-btn">Save Service</button></form></div><div class="table-wrap"><table class="table"><tr><th>ID</th><th>English</th><th>Sinhala</th><th>Category</th><th>Action</th></tr><?php $rs=$conn->query('SELECT * FROM services ORDER BY id DESC');while($x=$rs->fetch_assoc()):?><tr><td><?=$x['id']?></td><td><?=h($x['name_en'])?></td><td><?=h($x['name_si'])?></td><td><?=h($x['category'])?></td><td><a class="table-link" href="?tab=services&edit=<?=$x['id']?>">Edit</a> <form class="inline-form" method="post"><input type="hidden" name="entity" value="delete"><input type="hidden" name="type" value="services"><input type="hidden" name="id" value="<?=$x['id']?>"><button class="link-danger">Delete</button></form></td></tr><?php endwhile;?></table></div></div>
<?php elseif($tab==='vehicles'):?><div class="crud-grid"><div class="form-card"><h3><?= $editRow?"Edit Vehicle":"Add Vehicle" ?></h3><form method="post"><input type="hidden" name="entity" value="vehicles"><input type="hidden" name="id" value="<?= (int)($editRow["id"]??0) ?>"><label>Vehicle type</label><input name="vehicle_type" value="<?=h($editRow["vehicle_type"]??"")?>" required><label>Registration number</label><input name="registration_no" value="<?=h($editRow["registration_no"]??"")?>" required><label>Operator</label><input name="operator_name" value="<?=h($editRow["operator_name"]??"")?>"><label>Route</label><input name="route" value="<?=h($editRow["route"]??"")?>"><button class="primary-btn">Save Vehicle</button></form></div><div class="table-wrap"><table class="table"><tr><th>Type</th><th>Reg. No.</th><th>Operator</th><th>Route</th><th>Action</th></tr><?php $rs=$conn->query('SELECT * FROM vehicles ORDER BY id DESC');while($x=$rs->fetch_assoc()):?><tr><td><?=h($x['vehicle_type'])?></td><td><?=h($x['registration_no'])?></td><td><?=h($x['operator_name'])?></td><td><?=h($x['route'])?></td><td><a class="table-link" href="?tab=vehicles&edit=<?=$x['id']?>">Edit</a> <form class="inline-form" method="post"><input type="hidden" name="entity" value="delete"><input type="hidden" name="type" value="vehicles"><input type="hidden" name="id" value="<?=$x['id']?>"><button class="link-danger">Delete</button></form></td></tr><?php endwhile;?></table></div></div>
<?php elseif($tab==='stands'):?><div class="crud-grid"><div class="form-card"><h3><?= $editRow?"Edit Bus Stand":"Add Bus Stand" ?></h3><form method="post"><input type="hidden" name="entity" value="stands"><input type="hidden" name="id" value="<?= (int)($editRow["id"]??0) ?>"><label>Bus stand name</label><input name="name" value="<?=h($editRow["name"]??"")?>" required><label>District</label><select name="district" required><option <?=($editRow["district"]??"")==="Galle"?"selected":""?>>Galle</option><option <?=($editRow["district"]??"")==="Matara"?"selected":""?>>Matara</option><option <?=($editRow["district"]??"")==="Hambantota"?"selected":""?>>Hambantota</option></select><label>Address / details</label><input name="address" value="<?=h($editRow["address"]??"")?>"><button class="primary-btn">Save Bus Stand</button></form></div><div class="table-wrap"><table class="table"><tr><th>Name</th><th>District</th><th>Details</th><th>Action</th></tr><?php $rs=$conn->query('SELECT * FROM bus_stands ORDER BY id DESC');while($x=$rs->fetch_assoc()):?><tr><td><?=h($x['name'])?></td><td><?=h($x['district'])?></td><td><?=h($x['address'])?></td><td><a class="table-link" href="?tab=stands&edit=<?=$x['id']?>">Edit</a> <form class="inline-form" method="post"><input type="hidden" name="entity" value="delete"><input type="hidden" name="type" value="stands"><input type="hidden" name="id" value="<?=$x['id']?>"><button class="link-danger">Delete</button></form></td></tr><?php endwhile;?></table></div></div>
<?php elseif($tab==='documents'):?><div class="crud-grid"><div class="form-card"><h3><?= $editRow?'Edit Document':'Add Document' ?></h3><form method="post" enctype="multipart/form-data"><input type="hidden" name="entity" value="documents"><input type="hidden" name="id" value="<?= (int)($editRow['id']??0) ?>"><label>English title</label><input name="title_en" value="<?=h($editRow['title_en']??'')?>" required><label>Sinhala title</label><input name="title_si" value="<?=h($editRow['title_si']??'')?>" required><label>PDF file <?= $editRow?'(optional to keep current file)':'*' ?></label><input type="file" name="document_file" accept="application/pdf,.pdf" <?= $editRow?'':'required' ?>><?php if($editRow):?><p><a class="table-link" href="../<?=h($editRow['file_path'])?>" target="_blank">Open current PDF</a></p><?php endif;?><label class="choice-options"><input type="checkbox" name="active" value="1" <?=!isset($editRow['active']) || (int)$editRow['active']===1?'checked':''?>> Show in client documents</label><button class="primary-btn" type="submit">Save Document</button></form></div><div class="table-wrap"><table class="table"><thead><tr><th>English title</th><th>Sinhala title</th><th>File</th><th>Visibility</th><th>Action</th></tr></thead><tbody><?php $rs=$conn->query('SELECT * FROM documents ORDER BY id DESC');while($x=$rs->fetch_assoc()):?><tr><td><?=h($x['title_en'])?></td><td><?=h($x['title_si'])?></td><td><a class="table-link" href="../<?=h($x['file_path'])?>" target="_blank">Open PDF</a></td><td><?=((int)$x['active']===1)?'Visible':'Hidden'?></td><td><a class="table-link" href="?tab=documents&edit=<?=(int)$x['id']?>">Edit</a><?php if((int)$x['active']===1):?> <form class="inline-form" method="post"><input type="hidden" name="entity" value="delete"><input type="hidden" name="type" value="documents"><input type="hidden" name="id" value="<?=(int)$x['id']?>"><button class="link-danger" type="submit">Remove</button></form><?php endif;?></td></tr><?php endwhile;?></tbody></table></div></div>
<?php else: ?><div class="crud-grid"><div class="form-card"><h3><?= $editRow?"Edit FAQ":"Add FAQ / AI Knowledge" ?></h3><form method="post"><input type="hidden" name="entity" value="faqs"><input type="hidden" name="id" value="<?= (int)($editRow["id"]??0) ?>"><label>Intent</label><input name="intent" value="<?=h($editRow["intent"]??"")?>" required><label>Question</label><textarea name="question" required><?=h($editRow["question"]??"")?></textarea><label>Answer</label><textarea name="answer" required><?=h($editRow["answer"]??"")?></textarea><label>Language</label><select name="language"><option value="si" <?=($editRow["language"]??"")==="si"?"selected":""?>>Sinhala</option><option value="en" <?=($editRow["language"]??"")==="en"?"selected":""?>>English</option></select><button class="primary-btn">Save FAQ</button></form></div><div class="table-wrap"><table class="table"><tr><th>ID</th><th>Language</th><th>Question</th><th>Answer</th><th>Action</th></tr><?php $rs=$conn->query('SELECT * FROM faqs ORDER BY id DESC LIMIT 150');while($x=$rs->fetch_assoc()):?><tr><td><?=$x['id']?></td><td><?=h($x['language'])?></td><td><?=h($x['question'])?></td><td><?=h(mb_strimwidth($x['answer'],0,120,'...'))?></td><td><a class="table-link" href="?tab=faqs&edit=<?=$x['id']?>">Edit</a> <form class="inline-form" method="post"><input type="hidden" name="entity" value="delete"><input type="hidden" name="type" value="faqs"><input type="hidden" name="id" value="<?=$x['id']?>"><button class="link-danger">Delete</button></form></td></tr><?php endwhile;?></table></div></div><?php endif;?></div><?php include '../includes/footer.php'; ?>